package com.witchersbestiary.client.sorcery;
import net.minecraft.client.MinecraftClient;import net.minecraft.client.gui.DrawContext;import net.minecraft.client.gui.widget.ButtonWidget;import net.minecraft.registry.RegistryWrapper;import net.minecraft.text.Text;import vazkii.patchouli.api.*;import java.util.function.UnaryOperator;
public final class GrimoireComponent implements ICustomComponent {
 private int x,y,page;private transient ButtonWidget learn,cast;
 public void build(int x,int y,int page){this.x=x;this.y=y;this.page=page;}public void onVariablesAvailable(UnaryOperator<IVariable> lookup,RegistryWrapper.WrapperLookup registries){}
 public void onDisplayed(IComponentRenderContext c){learn=ButtonWidget.builder(Text.translatable("book.signs.learn"),b->SorceryClient.send(0)).dimensions(x+4,y+129,104,16).build();cast=ButtonWidget.builder(Text.translatable("sorcery.witchersbestiary.cast"),b->{SorceryClient.send(1);MinecraftClient.getInstance().setScreen(null);}).dimensions(x+4,y+148,104,16).build();c.addWidget(learn,page);c.addWidget(cast,page);}
 public void render(DrawContext draw,IComponentRenderContext context,float delta,int mx,int my){var c=MinecraftClient.getInstance();draw.drawCenteredTextWithShadow(c.textRenderer,Text.translatable("spell.witchersbestiary.icy_grasp"),x+55,y+2,0xff352c21);draw.drawCenteredTextWithShadow(c.textRenderer,Text.literal("❄"),x+55,y+16,0xff297ea6);int yy=y+33;for(var line:c.textRenderer.wrapLines(Text.translatable("sorcery.witchersbestiary.description").setStyle(context.getFont()),110)){draw.drawText(c.textRenderer,line,x,yy,context.getTextColor(),false);yy+=10;}int costY=y+75;for(var line:c.textRenderer.wrapLines(Text.translatable("sorcery.witchersbestiary.cost").setStyle(context.getFont()),110)){draw.drawText(c.textRenderer,line,x,costY,context.getTextColor(),false);costY+=10;}draw.drawText(c.textRenderer,Text.translatable("sorcery.witchersbestiary.cooldown"),x,y+98,context.getTextColor(),false);var view=SorceryClient.view;if(learn!=null){learn.active=view!=null&&!view.learned();learn.setMessage(Text.translatable(view!=null&&view.learned()?"book.signs.known":"book.signs.learn"));}if(cast!=null)cast.active=view!=null&&view.learned()&&view.cooldown()==0;}
}
